Looking at the examples, I notice that each non-zero colored shape should be **180° rotationally symmetric** (point-symmetric about its center). Where two shapes overlap, some cells show the wrong color, breaking the symmetry. The fix: find each shape's true center of symmetry, then for each cell, check its reflected counterpart — if the reflection has a different non-zero color, that cell should adopt the current shape's color.

**Algorithm:**
1. For each color, find its cells and bounding box center.
2. Search near the bounding box center for a point where ALL cells reflect to non-zero cells.
3. Where a reflected cell has a *different* non-zero color, claim it for this color.

```python
def solve(grid):
    rows = len(grid)
    cols = len(grid[0])
    from collections import defaultdict

    color_cells = defaultdict(list)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                color_cells[grid[r][c]].append((r, c))

    result = [row[:] for row in grid]

    for color, cells in color_cells.items():
        if len(cells) <= 1:
            continue

        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)

        bbox_cr2 = min_r + max_r
        bbox_cc2 = min_c + max_c

        best_center = None
        best_dist = float('inf')

        search_r = max_r - min_r + 2
        search_c = max_c - min_c + 2

        for cr2 in range(bbox_cr2 - search_r, bbox_cr2 + search_r + 1):
            for cc2 in range(bbox_cc2 - search_c, bbox_cc2 + search_c + 1):
                valid = True
                for r, c in cells:
                    mr = cr2 - r
                    mc = cc2 - c
                    if 0 <= mr < rows and 0 <= mc < cols:
                        if grid[mr][mc] == 0:
                            valid = False
                            break
                    else:
                        valid = False
                        break

                if valid:
                    dist = abs(cr2 - bbox_cr2) + abs(cc2 - bbox_cc2)
                    if dist < best_dist:
                        best_dist = dist
                        best_center = (cr2, cc2)

        if best_center is None:
            continue

        cr2, cc2 = best_center

        for r, c in cells:
            mr = cr2 - r
            mc = cc2 - c
            if 0 <= mr < rows and 0 <= mc < cols:
                if grid[mr][mc] != color and grid[mr][mc] != 0:
                    result[mr][mc] = color

    return result
